@startuml
class RepairShop {
  +name : string
  +address : string
  +numberOfEmployees : int
}

class Employee {
  +taxCode : string
  +address : string
  +phoneNumber : string
  +yearsOfService : int
}

class Director extends Employee {
  +age : int
}

class Repair {
  +code : string
  +checkInTime : datetime
  +checkInDate : date
  +returnTime : datetime
  +returnDate : date
}

class Vehicle {
  +model : string
  +type : string
  +licensePlate : string
  +yearOfRegistration : int
}

class Owner {
  +taxCode : string
  +address : string
  +phoneNumber : string
}

class Manager {
  +performStaffSeniorityAnalysis(repairShop : RepairShop) : float
  +performRepairDurationAnalysis(repairShop : RepairShop) : Repair
}

class AccountingOffice {
  +receiveManagementResults(repairShop : RepairShop)
}

class Customer {
  +calculateVehiclesBroughtIn(customer : Customer) : int
  +calculateRecentRepairs(customer : Customer) : int
}

RepairShop "1" *-- "1" Director : manages
RepairShop "1" *-- "1..*" Employee : employs
RepairShop "1" -- "*" Repair : performs
RepairShop "1" -- "1" Manager : managed by
RepairShop "1" -- "1" AccountingOffice : communicates to
Vehicle "1" -- "1" Owner : owned by
Vehicle "1" -- "*" Repair : undergoes
Owner "1" -- "1" Customer : is a
@enduml

